ui:{by:'made by',byTitle:'André Luiz on LinkedIn',examT:'On the exam (CKA)',lessons:'lessons',progress:'Progress',search:'Search lessons and concepts…',noResults:'Nothing found.',theme:'Theme',themeLight:'Light theme',themeDark:'Dark theme',inDiagram:'In this step',course:'Course',steps:'steps',lesson:'Lesson',of:'of',step:'Step',key:'Key idea',good:'Good to know',warn:'Watch out',changed:'What changed',copy:'Copy',copied:'Copied',copyFail:'Select and copy',end:'End of course',nextLesson:'Next lesson',next:'Next',replay:'Replay',pause:'Pause',resume:'Resume',full:'Full screen',inLesson:'In this lesson',back:'Back',kStep:'step',kReplay:'replay',kPause:'pause',learn:'You will learn',openMenu:'Open lessons',lang:'Language',leg_req:'request',leg_heavy:'heavy request',leg_hc:'health check',leg_bad:'failed request'},
